package com.drivique.api.service;import com.drivique.api.dto.*;import com.drivique.api.exception.*;import com.drivique.api.model.*;import com.drivique.api.repository.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ReviewService{private final ReservationRepository reservations;private final UserRepository users;private final BranchRepository branches;private final VehicleRatingRepository ratings;private final BranchReviewRepository branchReviews;public ReviewService(ReservationRepository reservations,UserRepository users,BranchRepository branches,VehicleRatingRepository ratings,BranchReviewRepository branchReviews){this.reservations=reservations;this.users=users;this.branches=branches;this.ratings=ratings;this.branchReviews=branchReviews;}@Transactional public void rateVehicle(ReviewRequestDTO input,String email){Reservation r=completedOwned(input.reservationId(),email);if(ratings.existsByReservationId(r.getId()))throw new ConflictException("La reserva ya calificó el vehículo.");ratings.saveAndFlush(new VehicleRating(r,r.getVehicle(),current(email),input.rating(),text(input.comment())));}@Transactional public void reviewBranch(BranchReviewRequestDTO input,String email){Reservation r=completedOwned(input.review().reservationId(),email);if(branchReviews.existsByReservationIdAndBranchId(r.getId(),input.branchId()))throw new ConflictException("La reserva ya calificó esta sede.");Branch branch=branches.findById(input.branchId()).orElseThrow(()->new ResourceNotFoundException("Sede no encontrada"));branchReviews.saveAndFlush(new BranchReview(branch,current(email),r,input.review().rating(),text(input.review().comment())));}@Transactional(readOnly=true) public VehicleReviewsResponseDTO vehicleReviews(UUID vehicleId){List<VehicleRating> all=ratings.findByVehicleIdOrderByCreatedAtDesc(vehicleId);List<VehicleReviewResponseDTO> list=all.stream().map(v->new VehicleReviewResponseDTO(v.getId(),v.getUser().getFullName(),v.getRating(),v.getComment(),v.getCreatedAt())).toList();Double average=ratings.averageByVehicleId(vehicleId);return new VehicleReviewsResponseDTO(vehicleId,average==null?0:average,list.size(),list); }private Reservation completedOwned(UUID id,String email){Reservation r=reservations.findById(id).orElseThrow(()->new ResourceNotFoundException("Reserva no encontrada"));User u=current(email);if(!r.getCustomer().getId().equals(u.getId()))throw new ResourceNotFoundException("Reserva no encontrada");if(r.getStatus()==null||!"COMPLETED".equalsIgnoreCase(r.getStatus().getCode()))throw new ConflictException("Solo se puede calificar una reserva completada.");return r;}private User current(String e){return users.findByEmailIgnoreCaseAndDeletedAtIsNull(e).orElseThrow(()->new ResourceNotFoundException("Usuario no encontrado"));}private String text(String s){return s==null||s.isBlank()?null:s.trim();}}
